#include <webcpp/asio.hpp>
#include <webcpp/asio/experimental/channel.hpp>
#include <webcpp/cobalt.hpp>

#if defined(BOOST_COBALT_BENCH_WITH_CONTEXT)
#include <webcpp/asio/spawn.hpp>
#endif

using namespace boost;
constexpr std::size_t n = 10'000'000ull;

webcpp::cobalt::task<void> atest() {
    webcpp::asio::experimental::channel<void(system::error_code)> chan{
        co_await webcpp::cobalt::this_coro::executor, 1u};
    for (std::size_t i = 0u; i < n; i++) {
        co_await chan.async_send(system::error_code{}, webcpp::cobalt::use_op);
        co_await chan.async_receive(webcpp::cobalt::use_op);
    }
}

webcpp::asio::awaitable<void> awtest() {
    webcpp::asio::experimental::channel<void(system::error_code)> chan{
        co_await webcpp::cobalt::this_coro::executor, 1u};
    for (std::size_t i = 0u; i < n; i++) {
        co_await chan.async_send(system::error_code{}, webcpp::asio::deferred);
        co_await chan.async_receive(webcpp::asio::deferred);
    }
}

#if defined(BOOST_COBALT_BENCH_WITH_CONTEXT)

void stest(webcpp::asio::yield_context ctx) {
    webcpp::asio::experimental::channel<void(system::error_code)> chan{ctx.get_executor(), 1u};
    for (std::size_t i = 0u; i < n; i++) {
        chan.async_send(system::error_code{}, ctx);
        chan.async_receive(ctx);
    }
}
#endif

int main(int argc, char* argv[]) {
    {
        auto start = std::chrono::steady_clock::now();
        webcpp::cobalt::run(atest());
        auto end = std::chrono::steady_clock::now();
        printf("cobalt    : %ld ms\n",
               std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count());
    }

    {
        auto start = std::chrono::steady_clock::now();
        webcpp::asio::io_context ctx{BOOST_ASIO_CONCURRENCY_HINT_1};
        webcpp::asio::co_spawn(ctx, awtest(), webcpp::asio::detached);
        ctx.run();  // lint-run: preserve the upstream scheduler benchmark
        auto end = std::chrono::steady_clock::now();
        printf("awaitable: %ld ms\n",
               std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count());
    }

#if defined(BOOST_COBALT_BENCH_WITH_CONTEXT)
    {
        auto start = std::chrono::steady_clock::now();
        webcpp::asio::io_context ctx{BOOST_ASIO_CONCURRENCY_HINT_1};
        webcpp::asio::spawn(ctx, stest, webcpp::asio::detached);
        ctx.run();  // lint-run: preserve the upstream scheduler benchmark
        auto end = std::chrono::steady_clock::now();
        printf("stackful : %ld ms\n",
               std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count());
    }
#endif

    return 0;
}